Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 12;
const int INF = 1000000;
const int MAXNODE = 205;

int N, T;
char g1[MAXN][MAXN], g2[MAXN][MAXN];
int zdist[MAXN][MAXN];
int okPair[MAXN][MAXN][MAXN][MAXN];

int dirX[4] = {-1,1,0,0};
int dirY[4] = {0,0,-1,1};

struct NetEdge { int a,b,c,f; };

int totNodes, src, snk;
int lvl[MAXNODE], it[MAXNODE], qarr[MAXNODE];
vector<NetEdge> E;
vector<int> G[MAXNODE];

void addEdge(int a,int b,int c) {
    E.push_back({a,b,c,0});
    G[a].push_back((int)E.size()-1);
    E.push_back({b,a,0,0});
    G[b].push_back((int)E.size()-1);
}

bool bfsLevel() {
    int h=0,t=0;
    qarr[t++]=src;
    memset(lvl,-1,totNodes*sizeof(lvl[0]));
    lvl[src]=0;
    while (h<t && lvl[snk]==-1) {
        int v=qarr[h++];
        for (int id : G[v]) {
            int w=E[id].b;
            if (lvl[w]==-1 && E[id].f < E[id].c) {
                qarr[t++]=w;
                lvl[w]=lvl[v]+1;
            }
        }
    }
    return lvl[snk]!=-1;
}

int augment(int v,int pushed) {
    if (!pushed) return 0;
    if (v==snk) return pushed;
    for (int &i=it[v]; i<(int)G[v].size(); ++i) {
        int id=G[v][i], w=E[id].b;
        if (lvl[w]!=lvl[v]+1) continue;
        int got=augment(w, min(pushed, E[id].c-E[id].f));
        if (got) {
            E[id].f += got;
            E[id^1].f -= got;
            return got;
        }
    }
    return 0;
}

int dinic() {
    int ans=0;
    while (bfsLevel()) {
        memset(it,0,totNodes*sizeof(it[0]));
        while (int pushed=augment(src,INF)) ans += pushed;
    }
    return ans;
}

bool canTravel(int sx,int sy,int tx,int ty) {
    if (g1[sx][sy]=='Y' || g1[sx][sy]=='Z' || g1[tx][ty]=='Y' || g1[tx][ty]=='Z')
        return false;
    int dist[MAXN*MAXN];
    for (int i=0;i<N*N;++i) dist[i]=INF;
    deque<int> dq;
    int start = sx*N+sy;
    dist[start]=0;
    dq.push_back(start);
    while (!dq.empty()) {
        int v = dq.front(); dq.pop_front();
        int x = v/N, y = v%N;
        if (x==tx && y==ty) return true;
        if (dist[v] >= T || dist[v] >= zdist[x][y]) continue;
        for (int d=0; d<4; ++d) {
            int nx=x+dirX[d], ny=y+dirY[d];
            if (nx<0||nx>=N||ny<0||ny>=N) continue;
            if (g1[nx][ny]=='Y'||g1[nx][ny]=='Z') continue;
            int nid=nx*N+ny;
            if (dist[nid]==INF && dist[v]+1 <= zdist[nx][ny]) {
                dist[nid]=dist[v]+1;
                dq.push_back(nid);
            }
        }
    }
    return false;
}

int main() {
    scanf("%d%d",&N,&T);
    for(int i=0;i<N;i++) scanf("%s",g1[i]);
    getchar();
    for(int i=0;i<N;i++) scanf("%s",g2[i]);

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            zdist[i][j]=INF;

    deque<pair<int,int>> q;
    for(int x=0;x<N;x++)
        for(int y=0;y<N;y++)
            if (g1[x][y]=='Z') {
                for(int d=0;d<4;d++) {
                    int nx=x+dirX[d], ny=y+dirY[d];
                    if (nx>=0&&nx<N&&ny>=0&&ny<N&&g1[nx][ny]!='Y') {
                        zdist[nx][ny]=1;
                        q.push_back({nx,ny});
                    }
                }
            }

    while(!q.empty()) {
        int x=q.front().first, y=q.front().second;
        q.pop_front();
        for(int d=0;d<4;d++) {
            int nx=x+dirX[d], ny=y+dirY[d];
            if (nx>=0&&nx<N&&ny>=0&&ny<N&&g1[nx][ny]!='Y'&&g1[nx][ny]!='Z'&&zdist[nx][ny]==INF) {
                zdist[nx][ny]=zdist[x][y]+1;
                q.push_back({nx,ny});
            }
        }
    }

    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++)
                    okPair[x1][y1][x2][y2] = canTravel(x1,y1,x2,y2)?1:0;

    src=0; snk=2*N*N+1; totNodes=2*N*N+2;

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++) {
            if(g1[i][j]>'0'&&g1[i][j]<='9')
                addEdge(src,1+i*N+j,g1[i][j]-'0');
            if(g2[i][j]>'0'&&g2[i][j]<='9')
                addEdge(N*N+1+i*N+j,snk,g2[i][j]-'0');
        }

    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++)
                    if(okPair[x1][y1][x2][y2])
                        addEdge(1+x1*N+y1,N*N+1+x2*N+y2,INF);

    printf("%d\n",dinic());
    return 0;
}
